(source: string): string => {
        if (!source.startsWith(typeormPathPrefix)) return source
        const fullPathRewrite = deepPathRewrites[source]
        if (fullPathRewrite) return fullPathRewrite
        const lastSlash = source.lastIndexOf("/")
        // No slash or trailing slash → no segment to rewrite
        if (lastSlash === -1 || lastSlash === source.length - 1) return source
        const lastSegment = source.slice(lastSlash + 1)
        const renamedSegment = typeRenames[lastSegment]
        if (!renamedSegment) return source
        return source.slice(0, lastSlash + 1) + renamedSegment
    }

commit_message:
fix: work around SWC compress bug (#95457)

Works around a compiler bug in `SwcJsMinimizerRspackPlugin` that we
found in #95394

Some conditionals were getting miscompiled, from this:
```ts
if (inputsFromNavigation) {
  if (areStagesCompatible) {
    const instantInputs = needsInstantValidation ? inputsFromNavigation : null
    const staticInputs = inputsFromNavigation
    return { instantInputs, staticInputs }
  }

  if (navigationHasAppShell(navigationKind)) {
    const instantInputs = needsInstantValidation ? inputsFromNavigation : null
    const staticInputs = LAZY_RUNTIME_PRERENDER
    return { instantInputs, staticInputs }
  }

  const instantInputs = needsInstantValidation ? LAZY_FULL_RENDER : null
  const staticInputs = inputsFromNavigation
  return { instantInputs, staticInputs }
}
```
into this (in
`packages/next/dist/compiled/next-server/app-page-turbo.runtime.dev.js`)
```js
if (inputsFromNavigation)
  return areStagesCompatible || navigationHasAppShell(navigationKind)
    ? {
        instantInputs: needsInstantValidation
          ? inputsFromNavigation
          : null,
        staticInputs: inputsFromNavigation,
      }
    : {
        instantInputs: needsInstantValidation ? LAZY_FULL_RENDER : null,
        staticInputs: inputsFromNavigation,
      }
```
In the compiled version, the three branches get incorrectly merged into
two: if `navigationHasAppShell(navigationKind)`, static inputs are
`inputsFromNavigation` instead of `LAZY_RUNTIME_PRERENDER`. We're
guessing that this is a bug in some optimization of conditional returns;
disabling `compress.conditionals` in the minimizer seems to work around
it.

