  schema: SqlSchemaIR,
  schemaName: string,
  nativeType: string,
): readonly string[] | null {
  const enumTypes = readPostgresSchemaIrAnnotations(schema).enumTypes;
  const existing = enumTypes?.[schemaName]?.[nativeType];
  if (!existing || existing.codecId !== PG_ENUM_CODEC_ID) {
    return null;
