  "/recommendations/track-click",
  browseLimiter,
  trackRecommendationClick
);

// Admin — recommendation & engagement analytics dashboard data.
partRouter.get(
  "/admin/recommendation-analytics",
  recommendLimiter,
  auth,
  admin,
  adminGetRecommendationAnalytics
);
partRouter.put(
  "/update/:id",
