          className="mt-8 w-full flex justify-center"
        >
          <div className="w-full max-w-6xl">
            <div className="heatmap-container rounded-3xl border border-[#37b54a]/40 bg-black/50 backdrop-blur-sm w-full p-4 sm:p-8 relative">

