  if (!actorUri || !actorUri.startsWith(`${base}/ap/users/`)) return null;
  const slug = slugFromActorUrl(actorUri);
  if (!slug) return null;
  try { return db.prepare('SELECT slug FROM sites WHERE slug = ?').get(slug) ? slug : null; }
  catch { return null; }
}
Guardianship.wireHandshake({
