                new RPCClient({
                    endpoint: 'ws://localhost',
                    identity: 'x',
                    protocols: ['ocpp1.6', 'echo1.0', 'other0.1'],
                    strictModeValidators: [getEchoValidator()],
                    strictMode: ['ocpp1.6', 'echo1.0'],
                });
            });

            assert.doesNotThrow(() => {
                new RPCClient({
                    endpoint: 'ws://localhost',
