'use client';

import React, { useEffect, useRef, useState } from 'react';
import { useChat } from '@ai-sdk/react';
import { DefaultChatTransport } from 'ai';
import { Streamdown } from 'streamdown';
import 'streamdown/styles.css';
import { useTranslation } from 'react-i18next';
import { ArrowUp, RotateCcw } from 'lucide-react';
import { SectionHeader } from '@/components/craft/section-header';
import { Reveal } from '@/components/craft/reveal';
import BackgroundPaths from '@/components/kokonutui/background-paths';
import AITextLoading from '@/components/kokonutui/ai-text-loading';
import { useAutoResizeTextarea } from '@/hooks/use-auto-resize-textarea';
import { cn } from '@/lib/utils';

const transport = new DefaultChatTransport({ api: '/api/chat' });

export function DavidAI() {
  const { t } = useTranslation();
  const [input, setInput] = useState('');
  const { messages, sendMessage, status, setMessages } = useChat({ transport });
  const scroller = useRef<HTMLDivElement>(null);
  const pinned = useRef(true);
  const { textareaRef, adjustHeight } = useAutoResizeTextarea({
    minHeight: 52,
    maxHeight: 160,
  });

  const isBusy = status === 'submitted' || status === 'streaming';
  const suggestions = t('chat.suggestions', {
    returnObjects: true,
  }) as string[];
  const thinkingStages = t('chat.thinkingStages', {
    returnObjects: true,
  }) as string[];

  useEffect(() => {
    const el = scroller.current;
    if (!el || !pinned.current) return;

    const frame = requestAnimationFrame(() => {
      el.scrollTo({
        top: el.scrollHeight,
        behavior: status === 'streaming' ? 'auto' : 'smooth',
      });
    });

    return () => cancelAnimationFrame(frame);
  }, [messages, status]);

  const handleScroll = () => {
    const el = scroller.current;
    if (!el) return;
    pinned.current = el.scrollHeight - el.scrollTop - el.clientHeight < 48;
  };

  const submit = (text: string) => {
    const value = text.trim();
    if (!value || isBusy) return;
    pinned.current = true;
    sendMessage({ text: value });
    setInput('');
    adjustHeight(true);
  };

  return (
    <section
      id="david-ai"
      className="relative overflow-clip py-16 sm:py-24 lg:py-32"
    >
      <BackgroundPaths className="text-primary opacity-70" />

      <div className="gutter relative">
        <SectionHeader title={t('chat.title')} legend={t('chat.label')} />

        <div className="mt-14 grid gap-10 lg:grid-cols-12 lg:gap-14">
          <div className="lg:col-span-5">
            <Reveal>
              <p className="type-body text-muted-foreground">
                {t('chat.description')}
              </p>

              <p className="type-label mt-10 mb-4 text-muted-foreground">
                {t('chat.suggestionsLabel')}
              </p>

              <ul className="flex flex-col gap-2">
                {suggestions.map((question) => (
                  <li key={question}>
                    <button
                      type="button"
                      onClick={() => submit(question)}
                      disabled={isBusy}
                      className="group flex w-full cursor-pointer items-center justify-between gap-4 border border-hairline px-4 py-3 text-left text-sm text-muted-foreground transition-colors hover:border-primary hover:text-foreground disabled:cursor-not-allowed disabled:opacity-50"
                    >
                      {question}
                      <ArrowUp className="h-3.5 w-3.5 shrink-0 rotate-45 text-primary transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                    </button>
                  </li>
                ))}
              </ul>
            </Reveal>
          </div>

          <div className="lg:col-span-7">
            <Reveal className="flex h-[32rem] flex-col border border-hairline bg-card sm:h-[34rem]">
              <div className="flex items-center justify-between border-b border-hairline px-5 py-3.5">
                <span className="type-label flex items-center gap-2.5">
                  <span className="relative flex h-1.5 w-1.5">
                    <span
                      className={cn(
                        'absolute inline-flex h-full w-full rounded-full bg-primary',
                        isBusy && 'animate-ping opacity-70',
                      )}
                    />
                    <span className="relative inline-flex h-1.5 w-1.5 rounded-full bg-primary" />
                  </span>
                  David AI
                </span>

                {messages.length > 0 ? (
                  <button
                    type="button"
                    onClick={() => setMessages([])}
                    className="type-label flex cursor-pointer items-center gap-1.5 text-muted-foreground transition-colors hover:text-foreground"
                  >
                    <RotateCcw className="h-3 w-3" />
                    {t('chat.reset')}
                  </button>
                ) : null}
              </div>

              <div
                ref={scroller}
                onScroll={handleScroll}
                className="chat-scroll flex-1 space-y-4 overflow-y-auto px-5 py-5"
                aria-live="polite"
                aria-atomic="false"
              >
                <p className="max-w-[88%] bg-surface px-4 py-3 text-[0.9375rem] leading-relaxed">
                  {t('chat.welcomeMessage')}
                </p>

                {messages.map((message, mi) => {
                  const isUser = message.role === 'user';
                  const isLast = mi === messages.length - 1;

                  return (
                    <div
                      key={message.id}
                      className={cn(
                        'flex',
                        isUser ? 'justify-end' : 'justify-start',
                      )}
                    >
                      <div
                        className={cn(
                          'max-w-[88%] px-4 py-3 text-[0.9375rem] leading-relaxed',
                          isUser
                            ? 'bg-primary text-primary-foreground'
                            : 'bg-surface text-foreground',
                        )}
                      >
                        {message.parts.map((part, pi) =>
                          part.type === 'text' ? (
                            isUser ? (
                              <span key={pi}>{part.text}</span>
                            ) : (
                              <Streamdown
                                key={pi}
                                mode={
                                  status === 'streaming' && isLast
                                    ? 'streaming'
                                    : 'static'
                                }
                                className="streamdown-chat"
                              >
                                {part.text}
                              </Streamdown>
                            )
                          ) : null,
                        )}
                      </div>
                    </div>
                  );
                })}

                {status === 'submitted' &&
                messages[messages.length - 1]?.role !== 'assistant' ? (
                  <div className="flex items-center gap-2.5 bg-surface px-4 py-3">
                    <AITextLoading
                      texts={thinkingStages}
                      className="type-label text-muted-foreground"
                    />
                    <span className="flex gap-1" aria-hidden="true">
                      <span className="dot-cycle h-1 w-1 rounded-full bg-primary" />
                      <span className="dot-cycle h-1 w-1 rounded-full bg-primary [animation-delay:0.18s]" />
                      <span className="dot-cycle h-1 w-1 rounded-full bg-primary [animation-delay:0.36s]" />
                    </span>
                  </div>
                ) : null}
              </div>

              <form
                onSubmit={(event) => {
                  event.preventDefault();
                  submit(input);
                }}
                className="border-t border-hairline p-3"
              >
                <div className="flex items-end gap-2 focus-within:outline-2 focus-within:outline-offset-4 focus-within:outline-ring">
                  <label htmlFor="david-ai-input" className="sr-only">
                    {t('chat.placeholder')}
                  </label>
                  <textarea
                    id="david-ai-input"
                    ref={textareaRef}
                    value={input}
                    rows={1}
                    placeholder={t('chat.placeholder')}
                    onChange={(event) => {
                      setInput(event.currentTarget.value);
