    switch (provider.constructor) {
      // @ts-ignore
      case this._sync_importWebsocket?.WebsocketProvider:
        // @ts-ignore
        return provider.synced
      // @ts-ignore
      case this._sync_importWebrtc?.WebrtcProvider:
