        return provider.signalingConns.some(signalingConn => signalingConn.connected)
      // @ts-ignore
      case this._sync_importWebrtcTrystero?.TrysteroProvider:
        // @ts-ignore
        return provider.room.synced
      default:
        // @ts-ignore
        return provider.connected || provider.synced
    }
