  }

  /**
   * @name (get) importIndexeddb
   * @returns {Promise<import("./dependencies/y-indexeddb.js")> | import("./dependencies/y-indexeddb.js")}
   */
  get importIndexeddb () {
    return this._importIndexeddb || (this._importIndexeddb = import('./dependencies/y-indexeddb.js')).then(module => (this._sync_ImportIndexeddb = module))
  }

  /**
   * @name (get) importIndexeddb
   * @returns {Promise<import("./dependencies/y-websocket")> | import("./dependencies/y-websocket")}
   */
  get importWebsocket () {
    return this._importWebsocket || (this._importWebsocket = import('./dependencies/y-websocket.js')).then(module => (this._sync_importWebsocket = module))
  }

  /**
   * @name (get) importIndexeddb
   * @returns {Promise<import("./dependencies/y-webrtc.js")> | import("./dependencies/y-webrtc.js")}
   */
  get importWebrtc () {
    return this._importWebrtc || (this._importWebrtc = import('./dependencies/y-webrtc.js')).then(module => (this._sync_importWebrtc = module))
  }

  /**
   * webrtc-trystero https://github.com/WinstonFassett/y-webrtc-trystero
   *
   * @name (get) importIndexeddb
   * @returns {Promise<import("./dependencies/y-webrtc-trystero.js")> | import("./dependencies/y-webrtc-trystero.js")}
   */
  get importWebrtcTrystero () {
    // get a new instance of trystero when this._importWebrtcTrystero got nulled, so that a new session id is disposed. else it does not properly work.
    return this._importWebrtcTrystero || (this._importWebrtcTrystero = import(`./dependencies/y-webrtc-trystero.js?version=${Math.random()}`)).then(module => (this._sync_importWebrtcTrystero = module))
  }

  /**
   * The namespace is prepended to the custom event names
   * priority of value appliance: options, attribute
   *
   * @param {string} value
   */
  set namespace (value) {
    if (value) this.setAttribute('namespace', value)
  }

  /**
   * @return {string}
   */
  get namespace () {
    // @ts-ignore
    return this.getAttribute('namespace')
  }

  /**
   * The room is used as the room name
   * priority of value appliance: url param, options, attribute
   *
   * @param {Promise<string>} value
   */
  set room (value) {
    this._room = value
    value.then(room => {
      if (room) this.setAttribute('room', room)
    })
  }

  /**
   * @return {Promise<string>}
   */
  get room () {
    // @ts-ignore
    return this._room
  }

  /**
   * priority of value appliance: url param, options, attribute
   *
   * @param {string} value
   */
  set websocketUrl (value) {
    this.setAttribute('websocket-url', value)
  }

  /**
   * @return {string}
   */
  get websocketUrl () {
    // @ts-ignore
    return this.getAttribute('websocket-url')
  }

  /**
   * priority of value appliance: url param, options, attribute
   *
   * @param {string} value
   */
  set webrtcUrl (value) {
    this.setAttribute('webrtc-url', value)
  }

  /**
   * @return {string}
   */
  get webrtcUrl () {
    // @ts-ignore
    return this.getAttribute('webrtc-url')
  }

  /**
   * @return {Promise<string>}
   */
  get fingerprint () {
    // FingerprintJS does not work with ES6 Imports and for that we fetch it
    return this._fingerprint || (this._fingerprint = import(`${this.importMetaUrl}dependencies/fp.min.js`).then(
      FingerprintJS => FingerprintJS.load()
    ).then(
      fp => fp.get()
    ).then(
      result => result.visitorId
    ).catch(error => 'no-fingerprint:' + error))
  }

  /**
   * @return {string}
   */
  get epoch () {
    return this._epoch || (this._epoch = EventDrivenYjs.epochDateNow)
  }

  /**
   * @return {string}
   */
  static get epochDateNow () {
    return JSON.stringify({ epoch: Date.now(), uuid: self.crypto.randomUUID() })
  }

  /**
   * @param {'session' | 'local'} name
   * @return {Promise<string>}
   */
  async getEpochStorage (name) {
    const key = `${this.namespace}${await this.room}-${name}-epoch`
    let epoch = self[`${name}Storage`].getItem(key)
    if (epoch) return epoch
    self[`${name}Storage`].setItem(key, String(epoch = this.epoch))
    return epoch
  }

  get globalEventTarget () {
    // @ts-ignore
    return this._globalEventTarget || (this._globalEventTarget = self.Environment?.activeRoute || document.body)
  }
}

