  if (_dividers[0]) _dividers[0].style.display = (!_textOff && !_mediaOff) ? '' : 'none';
  if (_dividers[1]) _dividers[1].style.display = _textOff ? 'none' : '';
  if (_dividers[2]) _dividers[2].style.display = _textOff ? 'none' : '';

