			this.gametype = args[1];
			this.conditions["gametype"] = args[1];
			switch (args[1]) {
				case "singles":
					this.players.p1.active = [null];
					this.players.p2.active = [null];
					break;
				case 'doubles':
					this.players.p1.active = [null, null];
					this.players.p2.active = [null, null];
