      setCurrentTime(new Date().toLocaleTimeString());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    if (name === "recurring") {
      setNewClass({ ...newClass, recurring: checked });
    } else if (name === "recurringDays") {
      const options = Array.from(e.target.selectedOptions, (option) => option.value);
      setNewClass({ ...newClass, recurringDays: options });
    } else {
      setNewClass({ ...newClass, [name]: value });
    }
  };

  const addClass = async (e) => {
    e.preventDefault();
    
    const validationErrors = validateClassData(newClass);
    if (validationErrors.length > 0) {
      showNotification(validationErrors[0], "error");
      return;
    }

    setIsLoading(true);
    await new Promise((resolve) => setTimeout(resolve, 500));

    const newClasses = processRecurringClasses(newClass, isEditing);

    if (isEditing) {
      setClasses(classes.map((cls) => cls.id === editId ? { ...newClass, id: editId } : cls));
      showNotification("Class updated successfully!");
    } else {
      setClasses([...classes, ...newClasses]);
      showNotification("Class(es) added successfully!");
    }

    setNewClass(getDefaultClassData());
    setIsEditing(false);
    setEditId(null);
    setIsLoading(false);
    setIsFormOpen(false);
  };

  const editClass = (cls) => {
    setNewClass(cls);
    setIsEditing(true);
    setEditId(cls.id);
    setIsFormOpen(true);
  };

  const deleteClass = (id) => {
    setClasses(classes.filter((cls) => cls.id !== id));
    showNotification("Class deleted successfully!");
  };

  const cancelEdit = () => {
    setNewClass(getDefaultClassData());
    setIsEditing(false);
    setEditId(null);
    setIsFormOpen(false);
  };

  // Drag and drop for list view
  const onDragEnd = (result) => {
    if (!result.destination) return;
    const reorderedClasses = Array.from(filteredClasses);
    const [movedClass] = reorderedClasses.splice(result.source.index, 1);
    reorderedClasses.splice(result.destination.index, 0, movedClass);
    const newClasses = classes.map((cls) => reorderedClasses.find((rCls) => rCls.id === cls.id) || cls);
    setClasses(newClasses);
  };

  // Filtered classes with memo
  const filteredClasses = useMemo(() => {
    return filterClasses(classes, {
      activeDay,
      type: filters.type,
      instructor: filters.instructor,
      searchTerm
    });
  }, [classes, activeDay, searchTerm, filters]);

  // Chart data preparation
  const statistics = useMemo(() => getClassStatistics(classes, days, classTypes), [classes, days, classTypes]);
  
  const barData = useMemo(() => getBarChartData(statistics.classCountByDay), [statistics.classCountByDay]);
  const pieData = useMemo(() => getPieChartData(statistics.typeCounts), [statistics.typeCounts]);
  const instructorData = useMemo(() => getInstructorChartData(statistics.instructorCount), [statistics.instructorCount]);
  
  // Line chart data (static for now)
  const lineData = useMemo(() => getLineChartData(), []);
  const lineOptions = useMemo(() => getLineChartOptions(), []);

  // Unique instructors for filter
  const uniqueInstructors = useMemo(() => getUniqueInstructors(classes), [classes]);

  // Calendar events - FIXED
  const events = useMemo(() => getCalendarEvents(filteredClasses), [filteredClasses]);

  // Export schedule
  const handleExportSchedule = () => {
    exportSchedule(classes);
    showNotification("Schedule exported successfully!");
  };

  // Import schedule
  const handleImportSchedule = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    importSchedule(
      file,
      (importedClasses) => {
        setClasses(importedClasses);
        showNotification("Schedule imported successfully!");
      },
      (errorMessage) => {
        showNotification(errorMessage, "error");
      }
    );
  };

  // Calendar event style
  const eventStyleGetter = (event) => {
    const backgroundColor = event.resource?.color || '#6A67CE';
    const style = {
      backgroundColor,
      borderRadius: '5px',
      opacity: 0.8,
      color: 'white',
      border: '0px',
      display: 'block'
    };
    return {
      style: style
    };
  };

  return (
    <div className="py-4 px-4 sm:px-6 lg:px-8 min-h-screen bg-gray-50 text-gray-900">
      {/* Notification */}
      {notification.show && (
        <div
          className={`fixed top-4 right-4 z-50 px-6 py-3 rounded-lg shadow-lg transition-all duration-300 ${
            notification.type === "error"
              ? "bg-rose-500 text-white"
              : "bg-emerald-500 text-white"
          }`}
        >
          {notification.message}
        </div>
      )}

      {/* Loading Spinner */}
      {isLoading && <Loading />}

      <div className="">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 mb-6">
          {/* Header */}
          <div className="text-start">
      <h1 className="text-3xl font-bold mb-2">Class Schedule Tracker</h1>
      <p className="text-gray-600 text-sm">
        Never miss a class again! Keep track of your weekly schedule with
        color-coded subjects.
      </p>
      <p className="text-sm text-gray-500 mt-2">
        Current Time: {currentTime}
      </p>
    </div>


          {/* Export/Import */}
          <div className="flex gap-4">
            <button
              onClick={handleExportSchedule}
              className="px-6 py-2 bg-teal-500 text-white rounded-lg font-medium hover:bg-teal-600 transition-all shadow-sm"
            >
              Export Schedule
            </button>
            <label className="px-6 py-2 bg-blue-500 text-white rounded-lg font-medium hover:bg-blue-600 transition-all shadow-sm cursor-pointer">
              Import Schedule
              <input
                type="file"
                accept=".json"
                onChange={handleImportSchedule}
                className="hidden"
              />
            </label>
          </div>
        </div>

        <div className="flex flex-col lg:flex-row gap-8">
          {/* Main Content - Schedule Display */}
          <div className="w-full lg:w-3/5 space-y-6">
            {/* Controls */}
            <div className="bg-white rounded-sm p-6 flex flex-wrap items-center justify-between gap-4 border border-gray-200">
              <div className="flex items-center space-x-2">
                <span className="text-sm font-medium">View:</span>
                <button
                  onClick={() => setViewMode("grid")}
                  className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
                    viewMode === "grid"
                      ? "bg-teal-100 text-teal-700"
                      : "text-gray-600 hover:bg-gray-100"
                  }`}
                >
                  Grid
                </button>
                <button
                  onClick={() => setViewMode("list")}
                  className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
                    viewMode === "list"
                      ? "bg-teal-100 text-teal-700"
                      : "text-gray-600 hover:bg-gray-100"
                  }`}
                >
                  List
                </button>
                <button
                  onClick={() => setViewMode("calendar")}
                  className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
                    viewMode === "calendar"
                      ? "bg-teal-100 text-teal-700"
                      : "text-gray-600 hover:bg-gray-100"
                  }`}
                >
                  Calendar
                </button>
              </div>

              <ScheduleFilters
                days={days}
                activeDay={activeDay}
                setActiveDay={setActiveDay}
                viewMode={viewMode}
                setViewMode={setViewMode}
                searchTerm={searchTerm}
                setSearchTerm={setSearchTerm}
                filters={filters}
                setFilters={setFilters}
                uniqueInstructors={uniqueInstructors}
                classTypes={classTypes}
              />
            </div>

            {/* Schedule Display */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5 }}
              className="bg-white rounded-2xl overflow-hidden border border-gray-200"
            >
              <div className="px-6 py-4 border-b border-gray-200 bg-gray-50 flex items-center justify-between">
                <h2 className="text-xl font-semibold">Weekly Schedule</h2>
                <span className="text-sm bg-teal-100 text-teal-700 px-3 py-1 rounded-full">
                  {filteredClasses.length} classes
                </span>
              </div>

              {filteredClasses.length === 0 ? (
                <EmptyState />
              ) : viewMode === "calendar" ? (
                <div className="p-6">
                  <Calendar
                    localizer={localizer}
                    events={events}
                    startAccessor="start"
                    endAccessor="end"
                    style={{ height: 600 }}
                    onSelectEvent={(event) => editClass(event.resource)}
                    eventPropGetter={eventStyleGetter}
                    views={['month', 'week', 'day']}
                    defaultView="week"
                    step={60}
                    showMultiDayTimes
                  />
                </div>
              ) : viewMode === "grid" ? (
                <ScheduleGrid 
                  classes={filteredClasses} 
                  onEdit={editClass} 
                  onDelete={deleteClass} 
                  calculateEndTime={calculateEndTime} 
                />
              ) : (
                <ListView
                  classes={filteredClasses}
                  onEdit={editClass}
                  onDelete={deleteClass}
                  calculateEndTime={calculateEndTime}
                  onDragEnd={onDragEnd}
                />  
              )}
            </motion.div>
          </div>

          {/* Charts Section */}
          <div className="w-full lg:w-2/5 space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2 gap-6">
              <BarChart barData={barData} />
              <ClassTypeChart pieData={pieData} />
              <WeeklyTrendChart lineData={lineData} lineOptions={lineOptions} />
              <InstructorDistributionChart instructorData={instructorData} />
            </div>
          </div>
        </div>
      </div>

      {/* Floating Action Button */}
      <FloatingActionButton onClick={() => setIsFormOpen(true)} />

      {/* Sidebar Form */}
      <Sidebar isOpen={isFormOpen} onClose={() => setIsFormOpen(false)}>
        <ClassForm
          newClass={newClass}
          handleChange={handleChange}
          addClass={addClass}
          isEditing={isEditing}
          cancelEdit={cancelEdit}
          days={days}
          colorOptions={colorOptions}
          classTypes={classTypes}
        />
      </Sidebar>
    </div>
  );
}

import React, { useState, useEffect } from 'react'
import { Link, matchPath, useLocation } from 'react-router-dom'
import { useSelector } from 'react-redux'

import { NavbarLinks } from "../../../data/navbar-links"
import studyNotionLogo from '../../assets/Logo/Logo-Full-Light.png'
import { fetchCourseCategories } from './../../services/operations/courseDetailsAPI';

import ProfileDropDown from '../core/Auth/ProfileDropDown'
import MobileProfileDropDown from '../core/Auth/MobileProfileDropDown'

import { AiOutlineShoppingCart } from "react-icons/ai"
import { MdKeyboardArrowDown } from "react-icons/md"




const Navbar = () => {
    // console.log("Printing base url: ", import.meta.env.VITE_APP_BASE_URL);
    const { token } = useSelector((state) => state.auth);
    const { user } = useSelector((state) => state.profile);
    // console.log('USER data from Navbar (store) = ', user)
    const { totalItems } = useSelector((state) => state.cart)
    const location = useLocation();

    const [subLinks, setSubLinks] = useState([]);
    const [loading, setLoading] = useState(false);


    const fetchSublinks = async () => {
        try {
            setLoading(true)
            const res = await fetchCourseCategories();
            // const result = await apiConnector("GET", categories.CATEGORIES_API);
            // const result = await apiConnector('GET', 'http://localhost:4000/api/v1/course/showAllCategories');
            // console.log("Printing Sublinks result:", result);
            setSubLinks(res);
        }
        catch (error) {
            console.log("Could not fetch the category list = ", error);
        }
        setLoading(false)
    }

    // console.log('data of store  = ', useSelector((state)=> state))


    useEffect(() => {
        fetchSublinks();
    }, [])


    // when user click Navbar link then it will hold yellow color
    const matchRoute = (route) => {
        return matchPath({ path: route }, location.pathname);
    }


    // when user scroll down , we will hide navbar , and if suddenly scroll up , we will show navbar 
    const [showNavbar, setShowNavbar] = useState('top');
    const [lastScrollY, setLastScrollY] = useState(0);
    useEffect(() => {
        window.addEventListener('scroll', controlNavbar);

        return () => {
            window.removeEventListener('scroll', controlNavbar);
        }
    },)

    // control Navbar
    const controlNavbar = () => {
        if (window.scrollY > 200) {
            if (window.scrollY > lastScrollY)
                setShowNavbar('hide')

            else setShowNavbar('show')
        }

        else setShowNavbar('top')

        setLastScrollY(window.scrollY);
    }



    return (
        <nav className={`z-[10] flex h-14 w-full items-center justify-center border-b-[1px] border-b-richblack-700 text-white translate-y-0 transition-all ${showNavbar} `}>
             {/* <nav className={` fixed flex items-center justify-center w-full h-16 z-[10] translate-y-0 transition-all text-white ${showNavbar}`}> */}
            <div className='flex w-11/12 max-w-maxContent items-center justify-between '>
                {/* logo */}
                <Link to="/">
                    <img src={studyNotionLogo} width={160} height={42} loading='lazy' />
                </Link>

                {/* Nav Links - visible for only large devices*/}
                <ul className='hidden sm:flex gap-x-6 text-richblack-25'>
                    {
                        NavbarLinks.map((link, index) => (
                            <li key={index}>
                                {
                                    link.title === "Catalog" ? (
                                        <div
                                            className={`group relative flex cursor-pointer items-center gap-1 ${matchRoute("/catalog/:catalogName")
                                                ? "bg-yellow-25 text-black rounded-xl p-1 px-3"
                                                : "text-richblack-25 rounded-xl p-1 px-3"
                                                }`}
                                        >
                                            <p>{link.title}</p>
                                            <MdKeyboardArrowDown />
                                            {/* drop down menu */}
                                            <div className="invisible absolute left-[50%] top-[50%] z-[1000] flex w-[200px] translate-x-[-50%] translate-y-[3em] 
                                                    flex-col rounded-lg bg-richblack-5 p-4 text-richblack-900 opacity-0 transition-all duration-150 group-hover:visible 
                                                    group-hover:translate-y-[1.65em] group-hover:opacity-100 lg:w-[300px]"
                                            >
                                                <div className="absolute left-[50%] top-0 z-[100] h-6 w-6 translate-x-[80%] translate-y-[-40%] rotate-45 select-none rounded bg-richblack-5"></div>
                                                {loading ? (<p className="text-center ">Loading...</p>)
                                                    : subLinks.length ? (
                                                        <>
                                                            {subLinks?.map((subLink, i) => (
                                                                <Link
                                                                    to={`/catalog/${subLink.name
                                                                        .split(" ")
                                                                        .join("-")
                                                                        .toLowerCase()}`}
                                                                    className="rounded-lg bg-transparent py-4 pl-4 hover:bg-richblack-50"
                                                                    key={i}
                                                                >
                                                                    <p>{subLink.name}</p>
                                                                </Link>
                                                            ))}
                                                        </>
                                                    ) : (
                                                        <p className="text-center">No Courses Found</p>
                                                    )}
                                            </div>
                                        </div>
                                    ) : (
                                        <Link to={link?.path}>
                                            <p className={`${matchRoute(link?.path) ? "bg-yellow-25 text-black" : "text-richblack-25"} rounded-xl p-1 px-3 `}>
                                                {link.title}
                                            </p>
                                        </Link>)
                                }
                            </li>
                        ))}
                </ul>




                {/* Login/SignUp/Dashboard */}
                <div className='flex gap-x-4 items-center'>
                    {
                        user && user?.accountType === "Student" && (
                            <Link to="/dashboard/cart" className="relative">
                                <AiOutlineShoppingCart className="text-[2.35rem] text-richblack-5 hover:bg-richblack-700 rounded-full p-2 duration-200" />
                                {totalItems > 0 && (
                                    <span className="absolute -bottom-2 -right-2 grid h-5 w-5 place-items-center overflow-hidden rounded-full bg-richblack-600 text-center text-xs font-bold text-yellow-100">
                                        {totalItems}
                                    </span>
                                )}
                            </Link>
                        )
                    }
                    {
                        token === null && (
                            <Link to="/login">
                                {/* <button className='border border-richblack-700 bg-richblack-800 px-[12px] py-[8px] text-richblack-100 rounded-md focus:outline-8 outline-yellow-50'> */}
                                <button className={` px-[12px] py-[8px] text-richblack-100 rounded-md 
                                 ${matchRoute('/login') ? 'border-[2.5px] border-yellow-50' : 'border border-richblack-700 bg-richblack-800'} `}
                                >
                                    Log in
                                </button>
                            </Link>
                        )
                    }
                    {
                        token === null && (
                            <Link to="/signup">
                                {/* <button className='border border-richblack-700 bg-richblack-800 px-[12px] py-[8px] text-richblack-100 rounded-md'> */}
                                <button className={` px-[12px] py-[8px] text-richblack-100 rounded-md 
                                 ${matchRoute('/signup') ? 'border-[2.5px] border-yellow-50' : 'border border-richblack-700 bg-richblack-800'} `}
                                >
                                    Sign Up
                                </button>
                            </Link>
                        )
                    }

                    {/* for large devices */}
                    {token !== null && <ProfileDropDown />}

                    {/* for small devices */}
                    {token !== null && <MobileProfileDropDown />}

                </div>
            </div>
        </nav>
    )
}

export default Navbar

