                />
              )}
            </div>

            <div className="lg:grid lg:grid-cols-2 lg:gap-4">
            {/* Graphe évolution totale */}
            {months.length >= 2 && (
              <div className="bg-white rounded-3xl p-4 border border-slate-100">
