                        />
                      )
                    })}
                  </LineChart>
                </ResponsiveContainer>
                {/* Légende */}
                <div className="flex flex-wrap gap-x-4 gap-y-1.5 mt-3 px-1">
                  {activeCategories.map(cat => (
