                      </div>
                      {/* Liste top 10 */}
                      <div className="divide-y divide-slate-50">
                        {byLabelForView.length === 0 ? (
                          <p className="px-4 py-6 text-sm text-slate-400 text-center">{t('history.no_expenses_short')}</p>
