    router: object
    scheduleItem: Function 
    caldav_accounts_id: string | null | undefined | unknown
    calendars_id: string| null | undefined| unknown
    fetchEvents: Function
    view : string | null
    updated: string | null

}
export interface filterInterface {
    logic: string;
