    "MY_DAY":{logic: "or", filter: {due:[0, getTodaysDateUnixTimeStamp()], label: [MYDAY_LABEL]}},
    "DUE_TODAY":{ logic: "or", filter: { due: [0, getTodaysDateUnixTimeStamp()] } },
