            const temp_menu =(  
                <Form.Select value={selectedValue}  onChange={menuOptionSelected} size="sm">
                        {allMenuOptions}
                    </Form.Select>

                    )

            setMenu(temp_menu)

        }
        return ()=>{
            isMounted = false
        }
    },[menuOptions, selectedValue])

    return(
        <div  style={{marginTop: 20}}>

        {menuOptionsSelect}
        <br />
        </div>
    )
}
export default HomeTasks;

