/* ═══════════════════════════════════════════
   CIRCULAR GOAL RING
═══════════════════════════════════════════ */
function GoalRing({ progress, isDark }) {
  const r = 36, c = 2 * Math.PI * r;
  const offset = c * (1 - Math.min(progress, 1));
  return (
    <svg width="88" height="88" style={{ transform: "rotate(-90deg)" }}>
