                              className="w-full px-3 py-1.5 rounded-md bg-zinc-950 text-zinc-100 text-sm ring-1 ring-zinc-700 focus:ring-amber-500 focus:outline-none font-mono"
                              autoComplete="off"
                            />
                            <p className="mt-1 text-[10px] text-zinc-400">
