        'text-halo-width': 1,
        'text-opacity': ['case', ['boolean', ['feature-state', 'hover'], false], 0.7, 1.0],
        'icon-opacity': ['case', ['boolean', ['feature-state', 'hover'], false], 0.7, 1.0],
