          ? prev.isDarkMode
          : getSystemThemePreference();
    console.log(
      'Theme preference:',
      isDarkMode ? 'dark' : 'light',
      IS_MOBILE
        ? '(mobile - system preference)'
        : prev.isDarkMode !== undefined
          ? '(saved preference)'
          : '(system preference)'
    );

    // Parse route data from URL
    let fromPoint = null;
    let toPoint = null;

    if (urlParams.from) {
      const [lng, lat] = urlParams.from.split(',').map(Number);
      if (!isNaN(lng) && !isNaN(lat)) {
        fromPoint = {
          result: {
            center: [lng, lat],
            place_name: 'Origem carregada da URL',
          },
        };
      }
    }

    if (urlParams.to) {
      const [lng, lat] = urlParams.to.split(',').map(Number);
      if (!isNaN(lng) && !isNaN(lat)) {
        toPoint = {
          result: {
            center: [lng, lat],
            place_name: 'Destino carregado da URL',
          },
        };
      }
    }

    // `flyto=lat,lng[,zoom]` triggers a Mapbox flyTo animation from the initial
    // viewport to this target as soon as the map is ready. The optional third
    // value animates zoom too (if omitted, current zoom is preserved).
    // Internally we convert to Mapbox's `[lng, lat]` center order.
    if (urlParams.flyto) {
      const [lat, lng, zoom] = urlParams.flyto.split(',').map(Number);
      if (Number.isFinite(lat) && Number.isFinite(lng)) {
        this.pendingFlyToTarget = {
          center: [lng, lat],
          zoom: Number.isFinite(zoom) ? zoom : null,
        };
      }
    }

    const embedMode = urlParams.embed;

