  };

  loadAirtableMetadata = async () => {
    try {
      const db = new AirtableDatabase();
      const records = await db.getMetadata();
      const list = Array.isArray(records) ? records : [];
      this.setState({ airtableMetadataRecords: list }, () => this.syncAirtableCityFields());
    } catch (e) {
      console.warn('Failed to load Airtable city metadata', e);
      this.setState({ airtableMetadataRecords: [] }, () => this.syncAirtableCityFields());
    }
  };

  syncAirtableCityFields = () => {
    const { airtableMetadataRecords, area } = this.state;
    if (!Array.isArray(airtableMetadataRecords)) return;
    const db = new AirtableDatabase();
    const fields = db.matchCityMetadataFields(airtableMetadataRecords, area);
    this.setState({ airtableCityFields: fields });
  };

  onChangeStrategy(strategy) {
    this.setState({ lengthCalculationStrategy: strategy });
  }

  toggleTheme(newIsDark) {
    const currentIsDark = this.state.isDarkMode;

    if (newIsDark !== undefined && newIsDark === currentIsDark) {
      return;
    }

    if (newIsDark === undefined) {
      newIsDark = !currentIsDark;
    }

    // Apply theme class to body
    document.body.className = newIsDark ? 'theme-dark' : 'theme-light';

    // // Update map style if default style is selected (not satellite)
    // if (!this.state.showSatellite) {
    //     const newMapStyle = newIsDark
    //         ? MAP_STYLES.DARK
    //         : MAP_STYLES.LIGHT;
    //     this.setState({ mapStyle: newMapStyle });
    // }

    this.setState(
      {
        layers: this.initLayers(this.state.layers, newIsDark, this.state.debugMode),
        isDarkMode: newIsDark,
      },
      () => {
        // TEMP while we don't update everything dynamically
        // window.location.reload();
        this.forceMapReinitialization();
        // Save preference to localStorage
        this.saveStateToLocalStorage();
      }
    );
  }

  toggleSidebar(state) {
    this.setState({ isSidebarOpen: state });
  }

  openAboutModal() {
    this.setState({ aboutModal: true, hideUI: true });
  }

  closeAboutModal() {
    this.setState({
      aboutModal: false,
      hideUI: false,
    });
  }

  openCityPicker() {
    this.setState({ aboutModal: false, hideUI: false });
    this.props.router.navigate({ search: '?buscar' });
  }

  openLayersLegendModal(scrollToSection = null) {
    const sectionId =
      typeof scrollToSection === 'string' || typeof scrollToSection === 'number'
        ? scrollToSection
        : null;
    this.setState({
      layersLegendModal: true,
      layersLegendScrollToSection: sectionId,
    });
  }

  closeLayersLegendModal() {
    this.setState({
      layersLegendModal: false,
      layersLegendScrollToSection: null,
    });
  }

  openPrivacyPolicyModal() {
    const navigate = this.props.router?.navigate;
    if (typeof navigate === 'function') {
      navigate(PRIVACY_POLICY_PATH);
      return;
    }
    this.setState({ privacyPolicyModal: true, hideUI: true });
  }

  closePrivacyPolicyModal() {
    const navigate = this.props.router?.navigate;
    const onPrivacyRoute = isPrivacyPolicyLocation(this.props.location?.pathname);

    if (onPrivacyRoute && typeof navigate === 'function') {
      if (window.history.length > 1) {
        navigate(-1);
      } else {
        const citySlug = this.getCanonicalRouteCitySlug();
        navigate(citySlug ? `/${citySlug}` : '/');
      }
    }

    this.setState((prev) => ({
      privacyPolicyModal: false,
      hideUI: prev.aboutModal,
    }));
  }

  syncPrivacyPolicyFromRoute() {
    const onPrivacyRoute = isPrivacyPolicyLocation(this.props.location?.pathname);
    if (onPrivacyRoute === this.state.privacyPolicyModal) return;

    this.setState((prev) => ({
      privacyPolicyModal: onPrivacyRoute,
      hideUI: onPrivacyRoute || prev.aboutModal,
      aboutModal: onPrivacyRoute ? false : prev.aboutModal,
    }));

    if (onPrivacyRoute) {
      document.title = 'Aviso de Privacidade — CicloMapa';
    } else {
      updateDocumentMeta(this.state.area, this.getPreferredCanonicalSlugForMeta(this.state.area));
    }
  }

  initLayers(prevLayersStates, isDarkMode, isDebugMode) {
    const layers = OSMController.getLayers(isDarkMode, isDebugMode);

    // Merge with locally saved state
    if (prevLayersStates && Object.keys(prevLayersStates).length > 0) {
      layers.forEach((l) => {
        if (prevLayersStates[l.id] !== undefined) {
          l.isActive = prevLayersStates[l.id];
        }
      });
    }

    return layers;
  }

  getStateFromLocalStorage() {
    const savedState = JSON.parse(window.localStorage.getItem('appstate'));
    console.debug('Retrived saved state from local storage:', savedState);
    return savedState || {};
  }

  saveStateToLocalStorage() {
    // requestAnimationFrame( () => {
    let layersStates = {};
    this.state.layers.forEach((l) => {
      layersStates[l.id] = l.isActive;
    });

    const viewport = this.getCurrentViewport();
    const state = {
      area: this.state.area,
      showSatellite: this.state.showSatellite,
      zoom: viewport.zoom,
      lng: viewport.lng,
      lat: viewport.lat,
      isSidebarOpen: this.state.isSidebarOpen,
      layersStates: layersStates,
      isDarkMode: this.state.isDarkMode,
      isTrackingUserLocation: this.state.isTrackingUserLocation,
    };

    let str = JSON.stringify(state);
    window.localStorage.setItem('appstate', str);
    // });
  }

  getParamsFromURL() {
    const possibleParams = [
      'z',
      'lat',
      'lng',
      'embed',
      'debug',
      'from',
      'to',
      'clean',
      'hideui',
      'dark',
      'flyto',
    ];
    const urlParams = new URLSearchParams(this.props.location.search);
    let paramsObj = {};

    possibleParams.forEach((p) => {
      let value = urlParams.get(p);
      if (value) {
        paramsObj[p] = value;
      }
    });

    console.debug('url params obj:', paramsObj);

    return paramsObj;
  }

  hasExplicitViewportInURL() {
    const params = new URLSearchParams(this.props?.location?.search || window.location.search);
    return params.has('lat') || params.has('lng') || params.has('z');
  }

  getCitySlugFromRoute() {
    const city = this.props?.router?.params?.city;
    if (!city || city === 'routes') {
      return null;
    }
    return city;
  }

  getNormalizedRouteCitySlug() {
    const citySlug = this.getCitySlugFromRoute();
    if (!citySlug) return null;
    return decodeURIComponent(citySlug).trim().toLowerCase();
  }

  getCanonicalRouteCitySlug() {
    const normalizedSlug = this.getNormalizedRouteCitySlug();
    if (!normalizedSlug) return null;
    const definition = getPredefinedCitySlugDefinition(normalizedSlug);
    if (!definition) return null;
    return getCanonicalCitySlug(normalizedSlug);
  }

  getCitySlugFromArea(area) {
    if (!area || typeof area !== 'string') return null;
    const primaryLabel = area.split(',')[0]?.trim();
    if (!primaryLabel) return null;
    const normalizedSlug = this.slugifyCityLabel(primaryLabel);
    if (!normalizedSlug) return null;

    const definition = getPredefinedCitySlugDefinition(normalizedSlug);
    if (!definition) return normalizedSlug;
    return definition.canonicalSlug || normalizedSlug;
  }

  getKnownCanonicalSlugFromArea(area) {
    if (!area || typeof area !== 'string') return null;
    const primaryLabel = area.split(',')[0]?.trim();
    if (!primaryLabel) return null;
    const normalizedSlug = this.slugifyCityLabel(primaryLabel);
    if (!normalizedSlug) return null;
    const definition = getPredefinedCitySlugDefinition(normalizedSlug);
    if (!definition) return null;
    return definition.canonicalSlug || normalizedSlug;
  }

  getPreferredCanonicalSlugForMeta(area) {
    return this.getKnownCanonicalSlugFromArea(area) || this.getCanonicalRouteCitySlug();
  }

  /** Single document title for sr-only h1 (matches route, not only geocoder area). */
  getSrOnlyDocumentTitle() {
    const slug = this.getCanonicalRouteCitySlug();
    if (!slug) return 'CicloMapa';
    const loc = getPredefinedCityStaticLocation(slug);
    const primary = loc?.areaLabel?.split(',')[0]?.trim();
    return primary ? `${primary} — CicloMapa` : 'CicloMapa';
  }

  getCanonicalCityIdentity(area) {
    const canonicalSlug = this.getKnownCanonicalSlugFromArea(area);
    if (!canonicalSlug) return null;

    const staticLocation = getPredefinedCityStaticLocation(canonicalSlug);
    const canonicalAreaLabel = staticLocation?.areaLabel || null;
    return { canonicalSlug, canonicalAreaLabel };
  }

  getStorageKeyForArea(area) {
    const identity = this.getCanonicalCityIdentity(area);
    // Prefer a stable “full name” key when we have it, so storage keys stay consistent
    // with the old format (city + region + country) while remaining locale-independent
    // within our app (it always comes from the catalog, not from geocoder language).
    if (identity?.canonicalAreaLabel) return identity.canonicalAreaLabel;
    if (identity?.canonicalSlug) return identity.canonicalSlug;

    // Fallback to the full `area` string.
    return area;
  }

  normalizeAreaLabelForDisplay(area) {
    if (!area || typeof area !== 'string') return area;
    const identity = this.getCanonicalCityIdentity(area);
    return identity?.canonicalAreaLabel || area;
  }

  slugifyCityLabel(label) {
    if (!label || typeof label !== 'string') return null;
    return label
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
  }

  normalizeCitySlugRouteIfNeeded() {
    const normalizedSlug = this.getNormalizedRouteCitySlug();
    if (!normalizedSlug) return false;

    const definition = getPredefinedCitySlugDefinition(normalizedSlug);
    const navigate = this.props.router?.navigate;
    if (!definition) return false;

    const canonicalSlug = getCanonicalCitySlug(normalizedSlug);
    if (canonicalSlug === normalizedSlug) return false;

    const isRoutesPath = /\/routes\/?$/.test(window.location.pathname);
    const canonicalPath = isRoutesPath ? `/${canonicalSlug}/routes` : `/${canonicalSlug}`;
    const newUrl = `${canonicalPath}${window.location.search || ''}`;

    if (typeof navigate === 'function') {
      navigate(newUrl, { replace: true });
    } else {
      window.history.replaceState(null, '', newUrl);
    }
    return true;
  }

  syncRouteSlugWithArea(area) {
    if (isPrivacyPolicyLocation(this.props.location?.pathname) || this.state.privacyPolicyModal) {
      return;
    }

    // Only suppress slug generation for bare-root visitors while the welcome modal is
    // still open. Adding a slug while the modal is showing would silently flip it to
    // "city mode". Once the user has dismissed the modal the URL should update freely.
    if (this.initialBareRootEntry && !this.getCanonicalRouteCitySlug() && this.state.aboutModal) {
      return;
    }

    const areaSlug = this.getCitySlugFromArea(area);
    if (!areaSlug) return;

    const routeSlug = this.getCanonicalRouteCitySlug();
    if (routeSlug === areaSlug) return;

    const hasRouteParams = this.state.fromPoint && this.state.toPoint;
    const nextPath = hasRouteParams ? `/${areaSlug}/routes` : `/${areaSlug}`;

    // Always embed the current viewport in the URL so that when componentDidUpdate
    // detects the slug change, hasExplicitViewportInURL() returns true and
    // resolveCitySlugToAreaAndViewport is not called (which would fly the map to the
    // city centre, overriding the user's current position).
    const params = new URLSearchParams(window.location.search);
    const viewport = this.getCurrentViewport();
    if (Number.isFinite(viewport.lat) && Number.isFinite(viewport.lng)) {
      params.set('lat', viewport.lat.toFixed(7));
      params.set('lng', viewport.lng.toFixed(7));
      params.set('z', viewport.zoom.toFixed(2));
    }
    const nextUrl = `${nextPath}${params.toString() ? '?' + params.toString() : ''}`;

    const navigate = this.props.router?.navigate;
    if (typeof navigate === 'function') {
      // Use replace so that continuous map panning across city boundaries does not
      // flood the browser history stack with intermediate-city entries.
      navigate(nextUrl, { replace: true });
    } else {
      window.history.replaceState(null, '', nextUrl);
    }
  }

  recordRecentlyVisitedCity(area) {
    if (!area) return;
    try {
      const slug = this.getKnownCanonicalSlugFromArea(area) || this.getCitySlugFromArea(area);
      if (!slug) return;

      const raw = window.localStorage.getItem(RECENT_CITIES_STORAGE_KEY);
      const parsed = raw ? JSON.parse(raw) : [];
      const list = Array.isArray(parsed) ? parsed : [];

      const next = [
        { slug, areaLabel: area, visitedAt: Date.now() },
        ...list.filter((item) => item && item.slug && item.slug !== slug),
      ].slice(0, MAX_RECENT_CITIES);

      window.localStorage.setItem(RECENT_CITIES_STORAGE_KEY, JSON.stringify(next));
    } catch (e) {
      // Non-critical UX: don't break city switching if storage isn't available.
      console.debug('[recent-cities] failed to record recently visited city:', e);
    }
  }

  resolveCitySlugToAreaAndViewport = async (citySlug) => {
    if (!citySlug) return;
    if (this.lastResolvedCitySlug === citySlug) return;

    this.lastResolvedCitySlug = citySlug;
    this._lastExplicitCityNavTimestamp = Date.now();

    try {
      const normalizedSlug = decodeURIComponent(citySlug).trim().toLowerCase();
      const predefined = getPredefinedCitySlugDefinition(normalizedSlug);
      const staticLocation = getPredefinedCityStaticLocation(normalizedSlug);
      console.debug('[slug-resolution] start', {
        citySlug,
        normalizedSlug,
        hasPredefinedDefinition: Boolean(predefined),
        hasStaticLocation: Boolean(staticLocation),
      });

      if (staticLocation) {
        console.debug('[slug-resolution] using static location', {
          citySlug: normalizedSlug,
          areaLabel: staticLocation.areaLabel,
          lat: staticLocation.lat,
          lng: staticLocation.lng,
        });
        this.setState(
          (prevState) => ({
            area: this.normalizeAreaLabelForDisplay(staticLocation.areaLabel || prevState.area),
            lat: staticLocation.lat,
            lng: staticLocation.lng,
            zoom: DEFAULT_ZOOM,
          }),
          () => {
            this.lastNotifiedCitySlugError = null;
            this.deferOrApplyCityFocus({
              lat: staticLocation.lat,
              lng: staticLocation.lng,
              placeName: staticLocation.areaLabel,
            });
          }
        );
        return;
      }

      const query = predefined?.query || normalizedSlug.replace(/[-_]+/g, ' ').trim();
      const countrycodes = predefined?.countrycodes;
      console.debug('[slug-resolution] falling back to Nominatim', {
        citySlug: normalizedSlug,
        query,
        countrycodes,
      });
      const baseOptions = {
        limit: 5,
        addressdetails: 1,
        layer: 'address',
        acceptLanguage: 'pt-BR,pt,en',
        countrycodes,
      };
      const strictOptions = {
        ...baseOptions,
        featureType: 'city',
      };
      const compatibilityOptions = {
        ...baseOptions,
        featureType: 'settlement',
      };

      let data = await OSMController.searchNominatim(query, strictOptions);
      if (!Array.isArray(data) || data.length === 0) {
        data = await OSMController.searchNominatim(query, compatibilityOptions);
      }

      if (!Array.isArray(data) || data.length === 0) {
        console.error('City slug resolution failed: empty Nominatim response after retries', {
          citySlug,
          query,
          strictOptions,
          compatibilityOptions,
          predefinedSlug: predefined,
        });
        if (this.lastNotifiedCitySlugError !== citySlug) {
          this.lastNotifiedCitySlugError = citySlug;
          appNotification.error({
            title: 'Nao foi possivel localizar a cidade',
            description:
              'Nao encontramos a cidade informada na URL. Verifique o nome e tente novamente.',
            duration: 5,
          });
        }
        this.lastResolvedCitySlug = null;
        return;
      }

      const best = data[0];
      const lat = parseFloat(best.lat);
      const lng = parseFloat(best.lon);
      const area = OSMController.normalizeAreaNameFromNominatimResult(best);
      const resolvedLat = Number.isFinite(lat) ? lat : null;
      const resolvedLng = Number.isFinite(lng) ? lng : null;

      console.debug('[slug-resolution] Nominatim resolved', {
        citySlug: normalizedSlug,
        query,
        area,
        lat,
        lng,
      });

      this.setState(
        (prevState) => ({
          area: this.normalizeAreaLabelForDisplay(area || prevState.area),
          lat: resolvedLat !== null ? resolvedLat : prevState.lat,
          lng: resolvedLng !== null ? resolvedLng : prevState.lng,
          zoom: DEFAULT_ZOOM,
        }),
        () => {
          this.lastNotifiedCitySlugError = null;
          const fallbackViewport = this.getCurrentViewport();
          const latUse = resolvedLat !== null ? resolvedLat : fallbackViewport.lat;
          const lngUse = resolvedLng !== null ? resolvedLng : fallbackViewport.lng;
          this.deferOrApplyCityFocus({ lat: latUse, lng: lngUse, placeName: area });
        }
      );
    } catch (e) {
      console.error('City slug resolution error:', e);
      if (this.lastNotifiedCitySlugError !== citySlug) {
        this.lastNotifiedCitySlugError = citySlug;
        appNotification.error({
          title: 'Erro ao buscar a cidade',
          description:
            'Houve um problema ao consultar o servico de localizacao. Tente novamente em instantes.',
          duration: 5,
        });
      }
      this.lastResolvedCitySlug = null;
    }
  };

  // Slug / URL resolution can run before the map exists (state.map is set after Map mounts).
  // We stash one target and fly once applyDeferredCityFocus runs from componentDidUpdate.
  deferOrApplyCityFocus({ lat, lng, placeName }) {
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;

    if (this.state.map) {
      try {
        flyMapToCityFocus(this.state.map, [lng, lat], placeName);
      } catch (e) {
        console.error('Failed to move map to city focus:', e);
      }
      this.deferredCityFocus = null;
      return;
    }

    this.deferredCityFocus = { lat, lng, placeName };
  }

  applyDeferredCityFocus() {
    if (!this.deferredCityFocus || !this.state.map) return;
    const { lat, lng, placeName } = this.deferredCityFocus;
    try {
      flyMapToCityFocus(this.state.map, [lng, lat], placeName);
    } catch (e) {
      console.error('Failed to apply deferred city focus:', e);
    }
    this.deferredCityFocus = null;
  }

  // Applies the `?flyto=lat,lng[,zoom]` URL param by animating the camera
  // from the current map center to the target with Mapbox's flyTo. We wait
  // for the map's first `load` event and then add a short pause so the user
  // perceives the origin before the camera starts moving.
  //
  // The URL param is intentionally NOT stripped, so refreshing the page
  // replays the animation. To keep the replay faithful, `updateURL` freezes
  // `lat`/`lng`/`z` writes while `flyto` is present (otherwise post-animation
  // map moves would overwrite the origin with the destination, leaving
  // nothing to fly from on the next load).
  applyPendingFlyTo() {
    if (!this.pendingFlyToTarget || !this.state.map) return;
    const map = this.state.map;
    const target = this.pendingFlyToTarget;
    this.pendingFlyToTarget = null;

    const doFly = () => {
      try {
        const flyOptions = {
          center: target.center,
          duration: 3000,
          essential: true,
        };
        if (target.zoom !== null) {
          flyOptions.zoom = target.zoom;
        }
        map.flyTo(flyOptions);
      } catch (e) {
        console.error('Failed to apply pending flyto:', e);
      }
    };

    const FLYTO_INITIAL_PAUSE_MS = 700;
    const scheduleFly = () => setTimeout(doFly, FLYTO_INITIAL_PAUSE_MS);

    if (map.loaded()) {
      scheduleFly();
    } else {
      map.once('load', scheduleFly);
    }
  }

  async reverseGeocodeURLPoints() {
    // Reverse geocode URL-loaded points to get proper place names
    if (
      this.state.fromPoint &&
      this.state.fromPoint.result.place_name === 'Origem carregada da URL'
    ) {
      try {
        trackCall({
          api: API_TYPES.MAPBOX_GEOCODING,
          details: `${this.state.fromPoint.result.center[1].toFixed(4)}, ${this.state.fromPoint.result.center[0].toFixed(4)}`,
        });
        const response = await fetch(
          `https://api.mapbox.com/geocoding/v5/mapbox.places/${this.state.fromPoint.result.center[0]},${this.state.fromPoint.result.center[1]}.json?access_token=${MAPBOX_ACCESS_TOKEN}&language=pt-BR`
        );
        const data = await response.json();
        if (data.features && data.features.length > 0) {
          const placeName = data.features[0].place_name;
          this.setState({
            fromPoint: {
              ...this.state.fromPoint,
              result: {
                ...this.state.fromPoint.result,
                place_name: placeName,
              },
            },
          });
        }
      } catch (error) {
        console.error('Error reverse geocoding from point:', error);
      }
    }

    if (this.state.toPoint && this.state.toPoint.result.place_name === 'Destino carregado da URL') {
      try {
        trackCall({
          api: API_TYPES.MAPBOX_GEOCODING,
          details: `${this.state.toPoint.result.center[1].toFixed(4)}, ${this.state.toPoint.result.center[0].toFixed(4)}`,
        });
        const response = await fetch(
          `https://api.mapbox.com/geocoding/v5/mapbox.places/${this.state.toPoint.result.center[0]},${this.state.toPoint.result.center[1]}.json?access_token=${MAPBOX_ACCESS_TOKEN}&language=pt-BR`
        );
        const data = await response.json();
        if (data.features && data.features.length > 0) {
          const placeName = data.features[0].place_name;
          this.setState({
            toPoint: {
              ...this.state.toPoint,
              result: {
                ...this.state.toPoint.result,
                place_name: placeName,
              },
            },
          });
        }
      } catch (error) {
        console.error('Error reverse geocoding to point:', error);
      }
    }
  }

  updateURL() {
    const currentParams = new URLSearchParams(window.location.search);

    // While `flyto` is present, keep `lat`/`lng`/`z` frozen at the original
    // values so refreshing the page replays the animation from the same origin.
    // Map moves (including the flyTo itself and user pans/zooms afterwards)
    // won't be reflected in the URL until `flyto` is removed.
    const hasFlytoParam = currentParams.has('flyto');

    if (!hasFlytoParam) {
      const viewport = this.getCurrentViewport();
      currentParams.set('lat', viewport.lat.toFixed(7));
      currentParams.set('lng', viewport.lng.toFixed(7));
      currentParams.set('z', viewport.zoom.toFixed(2));
    }

    if (this.state.debugMode) {
      currentParams.set('debug', 'true');
    } else {
      currentParams.delete('debug');
    }

    if (this.state.embedMode) {
      currentParams.set('embed', 'true');
    } else {
      currentParams.delete('embed');
    }

    if (this.state.cleanMode) {
      currentParams.set('clean', 'true');
    } else {
      currentParams.delete('clean');
    }

    if (this.state.darkModeFromUrl) {
      currentParams.set('dark', 'true');
    } else {
      currentParams.delete('dark');
    }

    if (this.state.hideUIFromUrl) {
      currentParams.set('hideui', 'true');
    } else {
      currentParams.delete('hideui');
    }

    if (this.state.fromPoint && this.state.toPoint) {
      currentParams.set(
        'from',
        `${this.state.fromPoint.result.center[0]},${this.state.fromPoint.result.center[1]}`
      );
      currentParams.set(
        'to',
        `${this.state.toPoint.result.center[0]},${this.state.toPoint.result.center[1]}`
      );
    } else {
      currentParams.delete('from');
      currentParams.delete('to');
    }

    const newSearch = currentParams.toString();

    // Determine the base path - use /routes/ when there are route parameters, otherwise keep current path
    let basePath = window.location.pathname;
    const hasRouteParams = this.state.fromPoint && this.state.toPoint;

    if (hasRouteParams) {
      if (!basePath.endsWith('/routes/') && !basePath.endsWith('/routes')) {
        basePath = basePath.endsWith('/') ? `${basePath}routes/` : `${basePath}/routes/`;
      }
    } else {
      basePath = basePath.replace(/\/routes\/?$/, '') || '/';
    }

    const newUrl = `${basePath}${newSearch ? '?' + newSearch : ''}`;

    // Use browser history API directly for reliable URL updates
    window.history.replaceState(null, '', newUrl);
  }

  isDataFresh(lastUpdatedAt) {
    const now = new Date();
    const dataLastUpdate = new Date(lastUpdatedAt);
    const ageInDays = Math.round((now - dataLastUpdate) / (24 * 60 * 60 * 1000));
    const isFresh = ageInDays < OSM_DATA_MAX_AGE_DAYS;

    if (isFresh) {
      console.debug(`Database data is fresh (${ageInDays} days old).`);
    } else {
      console.debug(
        `Database data is stale (${ageInDays} days old), fetching fresh data from OSM...`
      );
    }

    return isFresh;
  }

  forceUpdate() {
    Analytics.event('force_update', {
      city_name: this.state.area,
    });
    this.updateData(true);
  }

  abortCurrentOSMRequest() {
    if (!this.currentOSMRequest) {
      return;
    }
    this.currentOSMRequest.abort();
    this.currentOSMRequest = null;
  }

  cancelDataLoad() {
    this.abortCurrentOSMRequest();
    this.setState({ loading: false });
    appNotification.destroy();
  }

  geoJsonDiff(oldData, newData) {
    console.debug('oldData', oldData);
    console.debug('newData', newData);

    if (!(oldData && oldData.features && newData && newData.features)) {
      return;
    }

    let a = new Set(oldData.features.map((i) => i.id));
    let b = new Set(newData.features.map((i) => i.id));

    // @todo compare full data, not only IDs
    // let a = new Set(oldData.features.map(i => JSON.stringify(i)));
    // let b = new Set(newData.features.map(i => JSON.stringify(i)));

    let a_minus_b = new Set([...a].filter((x) => !b.has(x)));
    let b_minus_a = new Set([...b].filter((x) => !a.has(x)));

    // a_minus_b = [...a_minus_b].map(i => JSON.parse(i));
    // b_minus_a = [...b_minus_a].map(i => JSON.parse(i));

    a_minus_b = [...a_minus_b];
    b_minus_a = [...b_minus_a];

    // console.debug('Removed:', a_minus_b);
    // console.debug('Added:', b_minus_a);

    appNotification.success({
      title: 'Dados atualizados com sucesso',
      description:
        a_minus_b.length === 0 && b_minus_a.length === 0 ? (
          <div>Não houve alterações no mapa cicloviários desde a última atualização.</div>
        ) : (
          <div>
            <div>
              <IconAdd className="inline" /> <b>{b_minus_a.length}</b> adicionados
            </div>
            <div>
              <IconRemove className="inline" /> <b>{a_minus_b.length}</b> removidos
            </div>
          </div>
        ),
    });
  }

  // Sometimes some Overpass servers return empty results instead of an error state
  isOSMDataHealthy(oldData, newData) {
    let isHealthy, before, after;

    if (DISABLE_DATA_HEALTY_TEST) {
      isHealthy = true;
    }

    if (!oldData || !oldData.features) {
      isHealthy = true;
    } else {
      before = oldData && oldData.features.length;
      after = newData && newData.features.length;

      console.debug('before', before);
      console.debug('after', after);
      console.debug('diff', after - before);

      isHealthy = !(after === 0 || after < before * THRESHOLD_NEW_VS_OLD_DATA_TOLERANCE);
    }

    Analytics.event('get_from_osm', {
      city_name: this.state.area,
      is_healthy: isHealthy,
      new_features: after - before,
    });

    return isHealthy;
  }

  getDataFromOSM(options = {}) {
    const { areaName = this.state.area, forceUpdate, backgroundUpdate } = options;

    // Cancel any existing OSM request
    if (this.currentOSMRequest) {
      console.debug('Cancelling previous OSM request');
      // notification.warning({
      //     message: 'OSM Request Cancelled',
      //     description: 'Previous OSM request was cancelled to start a new one.',
      //     duration: 2
      // });
      this.abortCurrentOSMRequest();
    }

    if (!backgroundUpdate) {
      this.setState({ loading: true });
    }

    // const parts = areaName.split(',');
    // const city = parts[0];

    // notification.info({
    //     message: 'OSM Request Started',
    //     description: `Starting OSM data request for ${city}`,
    //     duration: 2
    // });

    // notification.info({
    //     message: `Carregando mapa cicloviário de ${city}`,
    //     description: 'Baixando dados atualizados do OpenStreetMap. Dependendo do tamanho da cidade, isso pode levar alguns segundos ou até mais de um minuto.',
    //     duration: 0
    // });

    this.currentOSMRequest = OSMController.getData({ area: areaName });
    return this.currentOSMRequest
      .then((newData) => {
        this.geoJsonDiff(this.state.geoJson, newData.geoJson);

        if (forceUpdate && !this.isOSMDataHealthy(this.state.geoJson, newData.geoJson)) {
          throw new Error('New data is not healthy.');
        } else {
          // Since this is a heavy operation we only do it when syncing with new OSM data
          const lengths = calculateLayersLengths(
            newData.geoJson,
            this.state.layers,
            this.state.lengthCalculationStrategy
          );

          if (SAVE_TO_FIREBASE) {
            const storageKey = this.getStorageKeyForArea(areaName);
            this.getStorage()
              .save(areaName, newData.geoJson, lengths, { storageKey })
              .then(() => {
                if (!IS_PROD) {
                  appNotification.success({
                    title: 'Banco de dados atualizado',
                    description:
                      'O banco do CicloMapa foi atualizado com a versão mais recente dos dados desta cidade.',
                  });
                }
              })
              .catch((e) => {
                console.error('Error saving lengths to database:', e);
                if (!IS_PROD) {
                  appNotification.error({
                    title: 'Erro ao atualizar banco de dados',
                    description:
                      'Por alguma razão não conseguimos atualizar o banco de dados com esta versão dos dados. Por favor tente novamente ou contate os desenvolvedores.',
                  });
                }
              });
          }

          this.setState({
            geoJson: newData.geoJson,
            dataUpdatedAt: new Date(),
            ...(backgroundUpdate ? {} : { loading: false }),
            lengths: lengths,
          });

          appNotification.destroy();

          // notification.success({
          //     message: 'OSM Request Completed',
          //     description: `Successfully loaded data for ${city}`,
          //     duration: 2
          // });
        }

        // Clear the current request reference
        this.currentOSMRequest = null;
      })
      .catch((e) => {
        console.error(e);
        this.setState({
          loading: false,
        });

        appNotification.destroy();

        // Check if the error is due to request abortion
        if (e.message === 'Request aborted') {
          console.debug('OSM request was cancelled due to a new request');
          // notification.warning({
          //     message: 'OSM Request Aborted',
          //     description: 'OSM request was cancelled due to a new request.',
          //     duration: 2
          // });
        } else {
          appNotification.error({
            title: 'Ops',
            description:
              'O OSM está mal humorado neste momento e não conseguimos acessar os dados. Tente novamente mais tarde.',
          });
        }

        // Clear the current request reference
        this.currentOSMRequest = null;
      });
  }

  updateData(forceUpdate) {
    if (this.state.area) {
      if (forceUpdate) {
        this.getDataFromOSM({ forceUpdate: true });
      } else {
        // Try to retrieve this area's geojson data from the database
        const storageKey = this.getStorageKeyForArea(this.state.area);
        this.getStorage()
          .load(this.state.area, { storageKey })
          .then((data) => {
            if (data) {
              const hasBoundaryFeature = ENABLE_BOUNDARY_LAYER
                ? data.geoJson?.features?.some((f) => f.properties?.boundary === 'administrative')
                : true;

              if (!this.isDataFresh(data.updatedAt) || !hasBoundaryFeature) {
                // Re-fetch when stale, or when cached GeoJSON lacks city boundary
                // (older saves / PMTiles export scripts only stored cyclepath ways).
                this.getDataFromOSM({ backgroundUpdate: true });
              }

              if (!data.lengths || FORCE_RECALCULATE_LENGTHS_ALWAYS) {
                console.debug('Recalculating lengths...');
                data.lengths = calculateLayersLengths(
                  data.geoJson,
                  this.state.layers,
                  this.state.lengthCalculationStrategy
                );
              }

              this.setState({
                geoJson: data.geoJson,
                lengths: data.lengths,
                dataUpdatedAt: new Date(data.updatedAt),
              });
            } else {
              console.debug(
                `Couldn't find previously saved data for area ${this.state.area}, hitting OSM...`
              );

              this.setState({
                geoJson: null,
                lengths: {},
              });

              this.getDataFromOSM();
            }
          })
          .catch((e) => {
            console.error(e);
            // notification['error']({
            //     message: 'Erro',
            //     description:
            //         'Ocorreu um erro ao acessar o banco de dados.',
            // });
          });
      }
    } else {
      this.setState({ loading: false });
    }
  }

  onMapStyleChange(newMapStyle) {
    this.setState({ mapStyle: newMapStyle });
  }

  onMapShowSatelliteChanged(showSatellite) {
    if (!ENABLE_SATELLITE_TOGGLE) {
      // Ensure satellite mode is never enabled when the flag is off.
      if (this.state.showSatellite !== false) {
        this.setState({ showSatellite: false });
      }
      return;
    }

    this.setState({ showSatellite: showSatellite });
  }

  onLayersChange(idOrChanges, newVal) {
    let newLayers = [...this.state.layers];

    // Handle batch updates (array of {id, isActive} objects)
    if (Array.isArray(idOrChanges)) {
      idOrChanges.forEach((change) => {
        const layerIndex = newLayers.findIndex((layer) => layer.id === change.id);
        if (layerIndex === -1) {
          console.warn(`onLayersChange: Layer with id ${change.id} not found`);
          return;
        }
        newLayers[layerIndex] = { ...newLayers[layerIndex], isActive: change.isActive };
      });
    } else {
      // Handle single layer update (backward compatibility)
      const layerIndex = newLayers.findIndex((layer) => layer.id === idOrChanges);
      if (layerIndex === -1) {
        console.warn(`onLayersChange: Layer with id ${idOrChanges} not found`);
        return;
      }
      newLayers[layerIndex] = { ...newLayers[layerIndex], isActive: newVal };
    }

    this.setState({ layers: newLayers });
  }

  downloadData() {
    Analytics.event('purchase', {
      items: [
        {
          item_name: this.state.area,
          item_category: 'download',
          item_variant: 'geojson file',
        },
      ],
    });

    // Enable only layers of type "way" to download
    const layerWays = this.state.layers.filter((l) => l.type === 'way');

    // Deep object clone
    var data = JSON.parse(JSON.stringify(this.state.geoJson));

    computeTypologies(data, layerWays);
    cleanUpOSMTags(data);
    downloadObjectAsJson(data, `ciclomapa-${this.state.area}`);
  }

  componentDidUpdate(prevProps, prevState) {
    if (this.props.location !== prevProps.location) {
      this.onRouteChanged();
      this.syncPrivacyPolicyFromRoute();
    }

    const prevCityParam = prevProps.router?.params?.city;
    const prevCitySlug = prevCityParam && prevCityParam !== 'routes' ? prevCityParam : null;
    const currCitySlug = this.getCitySlugFromRoute();
    if (prevCitySlug !== currCitySlug) {
      this.lastResolvedCitySlug = null;
      // Stamp the navigation timestamp immediately so that any in-flight stale geocodes
      // from the previous city are suppressed regardless of which branch below runs.
      // Without this, resolveCitySlugToAreaAndViewport might be skipped (e.g. when
      // hasExplicitViewportInURL is true) and the timestamp would never be updated,
      // letting stale geocodes overwrite the new city slug.
      this._lastExplicitCityNavTimestamp = Date.now();
      if (currCitySlug) {
        const routeWasNormalized = this.normalizeCitySlugRouteIfNeeded();
        if (routeWasNormalized) return;
        updateDocumentMeta(this.state.area, this.getPreferredCanonicalSlugForMeta(this.state.area));
        if (!this.hasExplicitViewportInURL()) {
          this.resolveCitySlugToAreaAndViewport(currCitySlug);
        }
      }
    }

    if (this.state.map && this.state.map !== prevState.map) {
      this.applyDeferredCityFocus();
      this.applyPendingFlyTo();
    }

    if (this.state.area !== prevState.area) {
      updateDocumentMeta(this.state.area, this.getPreferredCanonicalSlugForMeta(this.state.area));
      this.syncRouteSlugWithArea(this.state.area);

      console.debug(`Changed area from ${prevState.area} to ${this.state.area}`);

      Analytics.event('switch_city', {
        city_name: this.state.area,
      });

      if (this._preserveRoutePointsOnAreaChange) {
        this._preserveRoutePointsOnAreaChange = false;
      } else {
        this.directionsPanel.clearDirections();
      }

      this.recordRecentlyVisitedCity(this.state.area);

      this.updateData();

      if (Array.isArray(this.state.airtableMetadataRecords)) {
        this.syncAirtableCityFields();
      }

      if (this.state.area && String(this.state.area).trim()) {
        maybeAutoOpenWelcomeAboutModal({
          fromMount: false,
          embedMode: this.state.embedMode,
          openAboutModal: () => this.openAboutModal(),
        });
      }

      document.querySelector('.city-picker span')?.setAttribute('style', 'opacity: 1');

      // Only redo the query if we need new data
      // if (!doesAContainsB(largestBoundsYet, newBounds)) {
      //     this.updateData();
      //     largestBoundsYet = newBounds;

      //     if (DEBUG_BOUNDS_OPTIMIZATION) {
      //         this.updateDebugPolygon(largestBoundsYet, 1);
      //     }
      // }
    }

    if (this.state.isDarkMode !== prevState.isDarkMode) {
      if (!this.state.showSatellite) {
        const newMapStyle = this.state.isDarkMode ? MAP_STYLES.DARK : MAP_STYLES.LIGHT;
        this.setState({ mapStyle: newMapStyle });
      }
    }

    if (this.state.geoJson !== prevState.geoJson) {
      if (
        !this.state.geoJson ||
        (this.state.geoJson.features && this.state.geoJson.features.length === 0)
      ) {
        // @todo link to our tutorials and invite the user to start mapping it
        // notification['warning']({
        //     message: 'Ops',
        //     description:
        //         'Não há dados cicloviários para esta cidade. Que tal colaborar no OpenStreetMap?',
        //     // action: <a href={getOsmUrl(this.state.lat, this.state.lng, this.state.zoom)} target="_blank" rel="noopener noreferrer">Editar no OSM</a> // not available in current Ant Design version
        // });
      } else {
        // @todo this seem to be being called every time!!!!
        // Retrocompatibility case where lengths weren't saved to database
        // if (!this.state.lengths) {
        //     console.debug('database didnt have lengths, computing...');
        //     this.calculateLengths();
        // }
      }
    }

    if (
      this.state.zoom !== prevState.zoom ||
      this.state.lat !== prevState.lat ||
      this.state.lng !== prevState.lng ||
      this.state.fromPoint !== prevState.fromPoint ||
      this.state.toPoint !== prevState.toPoint
    ) {
      this.debouncedUpdateURL();
    }

    if (this.state.lengthCalculationStrategy !== prevState.lengthCalculationStrategy) {
      // @todo olha a gambiarra!
      // Deep clone geoJson data to force Mapbox to update the data layers
      const clone = JSON.parse(JSON.stringify(this.state.geoJson));
      this.setState({
        geoJson: clone,
        lengths: calculateLayersLengths(
          clone,
          this.state.layers,
          this.state.lengthCalculationStrategy
        ),
      });
    }

    // Persist UI state as soon as user-visible filters/preferences change.
    if (
      this.state.area !== prevState.area ||
      this.state.showSatellite !== prevState.showSatellite ||
      this.state.isSidebarOpen !== prevState.isSidebarOpen ||
      this.state.isDarkMode !== prevState.isDarkMode ||
      this.state.isTrackingUserLocation !== prevState.isTrackingUserLocation ||
      this.state.layers !== prevState.layers
    ) {
      this.saveStateToLocalStorage();
    }
  }

  calculateLengths() {
    this.setState({
      lengths: calculateLayersLengths(
        this.state.geoJson,
        this.state.layers,
        this.state.lengthCalculationStrategy
      ),
    });
  }

  updateLengths = () => {
    this.calculateLengths();
  };

  scheduleWelcomeMapBootAfterPaint() {
    if (this._welcomeMapBootScheduled || this.state.mapBootReady) return;
    this._welcomeMapBootScheduled = true;
    scheduleAfterFirstPaint(() => {
      if (this._unmounted) return;
      this.startDeferredMapBoot();
    });
  }

  startDeferredMapBoot() {
    if (this.state.mapBootReady) return;
    this.setState({ mapBootReady: true }, () => {
      this.updateData();
    });
  }

  componentDidMount() {
    if (!this.state.mapBootReady) {
      this.scheduleWelcomeMapBootAfterPaint();
    }

    updateDocumentMeta(this.state.area, this.getPreferredCanonicalSlugForMeta(this.state.area));

    // Initialize theme
    document.body.className = this.state.isDarkMode ? 'theme-dark' : 'theme-light';

    // Listen for system theme changes
    if (window.matchMedia) {
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      const handleThemeChange = (e) => {
        const newTheme = e.matches;
        this.toggleTheme(newTheme);
      };
      mediaQuery.addEventListener('change', handleThemeChange);

      // Store the listener reference for cleanup
      this.themeChangeListener = handleThemeChange;
    }

    if (!this.state.aboutModal) {
      maybeAutoOpenWelcomeAboutModal({
        fromMount: true,
        embedMode: this.state.embedMode,
        openAboutModal: () => this.openAboutModal(),
      });
    }

    window.addEventListener('beforeunload', (e) => {
      this.saveStateToLocalStorage();
    });

    this.reverseGeocodeURLPoints();

    // Warm up the things the route panel's "fill origin with my location"
    // depends on. Geolocation only warms up if permission was already granted,
    // so we don't pop a surprise prompt before the user asks for it.
    userLocationCache.warmUpIfAlreadyGranted();
    ensureGooglePlacesReady();

    const citySlug = this.getCitySlugFromRoute();
    if (citySlug) {
      const routeWasNormalized = this.normalizeCitySlugRouteIfNeeded();
      if (routeWasNormalized) return;
      if (!this.hasExplicitViewportInURL()) {
        this.resolveCitySlugToAreaAndViewport(citySlug);
      }
    }

    this.loadAirtableMetadata();
    this.syncPrivacyPolicyFromRoute();
  }

  componentWillUnmount() {
    this._unmounted = true;

    // Clean up theme change listener
    if (this.themeChangeListener && window.matchMedia) {
      const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      mediaQuery.removeEventListener('change', this.themeChangeListener);
    }

    // Cancel any pending OSM request
    if (this.currentOSMRequest) {
      console.debug('Cancelling OSM request on component unmount');
      // notification.info({
      //     message: 'OSM Request Cancelled',
      //     description: 'OSM request was cancelled due to component unmount.',
      //     duration: 2
      // });
      this.abortCurrentOSMRequest();
    }

    // Cancel any pending debounced URL updates
    if (this.debouncedUpdateURL) {
      this.debouncedUpdateURL.cancel();
    }
  }

  onRouteChanged() {
    // @todo Fix infinite loop
    // this.setState(this.getParamsFromURL());
  }

  // High-frequency position updates from pan/zoom. Intentionally NOT setState:
  // position is only needed for the URL + persistence, not for rendering, so we
  // keep it in an imperative holder and update the URL directly. This avoids the
  // full App/Map re-render that made panning janky.
  onMapPositionChange(pos) {
    if (pos && Number.isFinite(pos.lat) && Number.isFinite(pos.lng)) {
      this.mapPosition = { lat: pos.lat, lng: pos.lng, zoom: pos.zoom };
    }
    this.debouncedUpdateURL();
  }

  // Single source of truth for the current viewport. Prefers the live map (always
  // accurate), falling back to the imperative holder / state before the map mounts.
  getCurrentViewport() {
    const map = this.state.map;
    if (map && typeof map.getCenter === 'function') {
      const c = map.getCenter();
      return { lat: c.lat, lng: c.lng, zoom: map.getZoom() };
    }
    // Map not mounted: prefer state so state-driven viewport changes (city switch,
    // URL params) take precedence over a potentially stale imperative holder.
    return {
      lat: this.state.lat,
      lng: this.state.lng,
      zoom: this.state.zoom,
    };
  }

  // Exposed to render-time consumers (TopBar OSM link, EditModal, CitySwitcher) so
  // they read the live viewport without us having to re-render on every pan.
  getMapViewport() {
    return this.getCurrentViewport();
  }

  onMapMoved(newState) {
    // Area/city change path (rare): this DOES go through setState because `area`
    // is rendered and drives data loading. Keep the imperative position holder in
    // sync so URL/persistence stay correct even before the next pan.
    if (newState && Number.isFinite(newState.lat) && Number.isFinite(newState.lng)) {
      this.mapPosition = { lat: newState.lat, lng: newState.lng, zoom: newState.zoom };
    }
    // This does NOT control the map - the map manages its own position
    requestAnimationFrame(() => {
      const nextState = { ...newState };
      if (typeof nextState.area === 'string' && nextState.area.trim()) {
        const normalized = this.normalizeAreaLabelForDisplay(nextState.area);

        // Guard against stale reverse-geocode results: a geocode that was *requested before*
        // an explicit city navigation (picker, direct URL) can resolve afterwards and overwrite
        // the new slug.  We detect this by comparing the geocode's request timestamp
        // (_geocodeRequestTime, set in Map.onMapMoveEnded) against the last navigation
        // timestamp.  Geocodes requested after the navigation are always accepted.
        const routeSlug = this.getCanonicalRouteCitySlug();
        if (normalized && routeSlug) {
          const candidateSlug = this.getCitySlugFromArea(normalized);
          const geocodeRequestTime = nextState._geocodeRequestTime ?? Date.now();
          const isStaleGeocode = geocodeRequestTime < this._lastExplicitCityNavTimestamp;
          if (candidateSlug && candidateSlug !== routeSlug && isStaleGeocode) {
            // Stale geocode result — drop the area update to protect the current slug.
            delete nextState.area;
          } else {
            nextState.area = normalized;
          }
        } else {
          nextState.area = normalized;
        }
      }
      delete nextState._geocodeRequestTime;
      this.setState(nextState);
    });
  }

  setMapRef(map) {
    this.setState({ map });
  }

  setDirectionsPanelRef(directionsPanel) {
    this.directionsPanel = directionsPanel;
  }

  onDirectionsPanelToggle(isOpen) {
    this.setState({ isDirectionsPanelOpen: isOpen });
  }

  setFromPoint = (point) => {
    this.setState({ fromPoint: point });
  };

  setToPoint = (point) => {
    this.setState({ toPoint: point });
  };

  clearRoutePoints = () => {
    this.setState({ fromPoint: null, toPoint: null });
  };

  setArea(newArea, options = {}) {
    const normalizedArea = this.normalizeAreaLabelForDisplay(newArea);
    if (normalizedArea && normalizedArea !== this.state.area) {
      // Transient flag consumed once in componentDidUpdate's area-change branch
      // so that programmatic area switches (e.g. auto-switching to match a
      // selected route point) don't wipe out the user's from/to points.
      this._preserveRoutePointsOnAreaChange = options.keepRoutePoints === true;
      this.setState({ area: normalizedArea });
    }
  }

  clearGlobalSearchPin = () => {
    this.setState({ globalSearchPin: null });
  };

  handleGlobalSearchPlaceSelect = async ({
    lng,
    lat,
    areaContext,
    title,
    address,
    placeTypes,
    placeId,
  }) => {
    const types = Array.isArray(placeTypes) ? placeTypes : [];
    const isAreaBrowse = isAreaBrowsePlaceResult(types);
    const zoom = isAreaBrowse ? DEFAULT_ZOOM : 16;
    let rawArea = areaContext != null ? String(areaContext).trim() : '';
    if (!rawArea) {
      try {
        const rev = await reverseGeocodePlace({ lng, lat });
        rawArea = rev?.place_name ? String(rev.place_name).trim() : '';
      } catch (e) {
        console.debug('[global-search] reverse geocode for app area failed', e);
      }
    }
    if (!rawArea) {
      rawArea = this.state.area ? String(this.state.area).trim() : '';
    }
    const normalizedArea = this.normalizeAreaLabelForDisplay(rawArea);

    const nextState = {
      area: normalizedArea || this.state.area,
      lat,
      lng,
      zoom,
      globalSearchPin: null,
    };

    if (!isAreaBrowse) {
      nextState.globalSearchPin = {
        lng,
        lat,
        title: title || '',
        address: address || '',
        placeTypes: types,
        placeId: placeId != null ? String(placeId) : '',
        areaContext: rawArea || '',
      };
    }

    this.setState(nextState, () => {
      if (!this.state.map) return;
      if (isAreaBrowse) {
        const placeName = title || normalizedArea || rawArea || '';
        this.deferOrApplyCityFocus({ lat, lng, placeName });
        return;
      }
      this.state.map.flyTo({
        center: [lng, lat],
        zoom,
        duration: 1500,
      });
    });
  };

  forceMapReinitialization() {
    this.setState((prevState) => ({
      mapKey: prevState.mapKey + 1,
    }));
  }

  render() {
    const handlers = {
      downloadData: this.downloadData,
      onMapMoved: this.onMapMoved,
