let newrelic;
const isNewRelicEnabled =
  !process.env.DISABLE_NEW_RELIC || process.env.DISABLE_NEW_RELIC !== "true";

if (isNewRelicEnabled) {
  // newrelic@14 crashes instrumenting the mongodb@7 driver; disable just that.
