              handleOuterTabChange('release-notes');
            }}>
              {t('releaseNotes')}
            </a> • 
            <a href="#" onClick={(e) => {
              e.preventDefault();
              handleOuterTabChange('readme');
            }}>
              {t('help')}
            </a> • 
            <a href="#" onClick={(e) => {
              e.preventDefault();
              handleOuterTabChange('templates');
            }}>
              {t('templates')}
            </a>
          </div>
          <LanguageSelector />
        </div>
