      task1.date = task2.date;
      task1.update = true;
    }
    else {task1.date = task2.date;
    task1.update = true;}
  }
  if (task1.finish != task2.finish){
    if (task1.finish == false) {
      task1.finish = true;
      task1.update = true;
    }
    else {
      task2.finish = true;
      task2.update = true;
    }
  }
