    actionsCell.appendChild(deleteButton);

    taskRow.appendChild(statusCell);
    taskRow.appendChild(taskDescription);
    taskRow.appendChild(priorityCell);
    taskRow.appendChild(dueDateCell);
    taskRow.appendChild(actionsCell);

    return taskRow;
}

