            let i = e.innerText
                , n = e.parentElement.parentElement.parentElement.querySelector(`.${prefix}mt${suffix}`).children[0].className
                , s = n.split("-")[1];
            return n.split("-")[2] + "-" + (s < 10 ? "0" + s : s) + "-" + (i < 10 ? "0" + i : i)
        }
