        ? location.search.replace(/(page=)(\d+)/, `$1${page}`)
        : `?page=${page}`
      const jumpUrl = location.pathname + search

      history.push(jumpUrl)
    },
    [queryParams, location.pathname]
  )

  return {
    dataList,
    loading,
    pagination: {
      ...pagination,
      onChange: handlePageChange
    },
    onFetch
  }
}

