                <select id="items" onChange={() => chooseAmount()}>
                  {options}
                </select>
              </label>
              <h6>
                <button 
                  type="button"
                  className="btn btn-warning" 
                  onClick={() => addToCart(id, selectedAmount)}
                >
                  Add to cart
                </button>
              </h6>
            </div>
          )
        }
      </h3>
      {
        isProductInCart
