  const nameProp = useRef(name);
  const uniqueIDFromContext = useContext(IndexContext);
  let uniqueIDarrayContext =
    uniqueIDFromContext !== undefined ? uniqueIDFromContext.id : 1;
  const setNameProp = useCallback(index => {
