function getRouteMetaMap () {
  const getMap: any = (routeList = [], prePath = '') => {
    let map = {}
    routeList.forEach((v: RoutesItemTypeNew) => {
      v.meta = v.meta || {}
      if (v.redirect || v.path === '*') {
        return
      }
      let currentPath = prePath + v.path
      if (v.path === '/') {
        currentPath = ''
      } else {
        map = {
          ...map,
          [currentPath]: v.meta || {}
        }
      }
      if (v.children) {
        map = {
          ...map,
          ...getMap(v.children, currentPath + '/')
        }
      }
    })
    return map
  }
  return getMap(routes)
}

