					/>
					<VolValue>{volume}</VolValue>
				</VolumeBox>
			)}
			<Flex>
				<IconButton handleClick={() => playNextPrev(-1)}>
					<TbPlayerTrackPrev />
				</IconButton>
				{isPaused ? (
					<IconButton handleClick={() => handlePlayingMusic(true)}>
						<TbPlayerPause />
					</IconButton>
				) : (
					<IconButton handleClick={() => handlePlayingMusic(false)}>
						<TbPlayerPlay />
					</IconButton>
				)}

				<IconButton handleClick={() => playNextPrev(1)}>
					<TbPlayerTrackNext />
				</IconButton>
