function processInlineImages(
  html: string,
  attachments: EmailAttachment[]
): string {
  if (!html) return html;


  const cidMap = new Map<string, EmailAttachment>();
  attachments.forEach((att) => {
    if (att.contentId) {
      cidMap.set(att.contentId, att);
    }
  });

  return html.replace(/src=["']cid:([^"']+)["']/g, (match, cid) => {
