    if(b.actions) meta.push(b.actions+' action'+(b.actions>1?'s':''));
    if(meta.length) lines.push('▤ '+meta.join(' · '));


    const lay = layer && layer.per.get(id);
    if(lay) lines.unshift((layer.kind==='owner'?'☗ ':layer.kind==='heat'?'▮ ':'⚠ ')+lay.text);
    const W=272;
