  return {
    ...api,
    memoryStore,
    memoryService,
    ...(closeLocalMemory
      ? {
          close: async () => {
            try {
              await close?.();
            } finally {
              closeLocalMemory();
            }
          },
        }
      : {}),
    smithers(build, smithersOpts) {
      return {
        ...smithers(build, smithersOpts),
