function MyApp({ Component, pageProps }) {
  const [cart, setCart] = useState({});
  const [subTotal, setSubTotal] = useState(0);
  const [loggedIn, setLoggedIn] = useState(false);
  const [userData, setUserData] = useState({});
  const [progress, setProgress] = useState(0);

  const router = useRouter();
  const fetchuser = async () => {
    const token = localStorage.getItem("token");
    try {
      const response = await axios.post(
        `${baseUrl}/api/fetchuserdata`,
        { data: token }
        );
        if (response.data) {
          setUserData(response.data.user);
        }
      } catch (error) {
        console.log(error);
        toast.error(error.response.data.error);
      }
  };

  useEffect(() => {
    router.events.on("routeChangeStart", () => {
      setProgress(40);
    });
    router.events.on("routeChangeComplete", () => {
      setProgress(100);
    });
    if (localStorage.getItem("token")) {
      fetchuser();
      setLoggedIn(true);
    } else {
      setLoggedIn(false);
    }
  }, [router.route]);

  useEffect(() => {


    try {
      if (localStorage.getItem("cart")) {
        setCart(JSON.parse(localStorage.getItem("cart")));
        saveCart(JSON.parse(localStorage.getItem("cart")));
      }
    } catch (error) {
      toast.error(error.message);
      console.error(error);
      localStorage.clear();
    }
  }, []);

  const logout = () => {
    localStorage.removeItem("token");
    router.push("/");
    setLoggedIn(false);
  };

  const saveCart = (myCart) => {
    localStorage.setItem("cart", JSON.stringify(myCart));
    let subt = 0;
    let keys = Object.keys(myCart);
    for (let i = 0; i < keys.length; i++) {
      subt += myCart[keys[i]].price * myCart[keys[i]].qty;
    }
    setSubTotal(subt);
  };

  const addToCart = (itemCode, qty, price, name, size, variant, img) => {
    let newCart = cart;

    if (itemCode in cart && size === cart[itemCode].size) {
      newCart[itemCode].qty = newCart[itemCode].qty + qty;
    } else {
      newCart[itemCode] = { itemCode, qty, price, name, size, variant, img };
    }
    console.log("newcart",newCart)
    setCart(newCart);
    saveCart(newCart);
  };

  const buyNow = (itemCode, qty, price, name, size, variant, img) => {
    let newCart = {};
    newCart[itemCode] = { qty: 1, price, name, size, variant, img };
    setCart(newCart);
    saveCart(newCart);
    router.push("/checkout");
  };

  const clearCart = () => {
    setCart({});
    saveCart({});
    localStorage.removeItem("cart");
  };

  const removeFromCart = (itemCode, qty, price, name, size, variant) => {
    let newCart = cart;
    if (itemCode in cart) {
      newCart[itemCode].qty = newCart[itemCode].qty - qty;
    }
    if (newCart[itemCode]["qty"] <= 0) {
      delete newCart[itemCode];
    }
    setCart(newCart);
    saveCart(newCart);
  };

  const cartLength = Object.keys(cart).length || 0;

  return (
    <>
      <Provider store={store}>
        <LoadingBar

          color="#ec4899"
          progress={progress}
          waitingTime={400}
          onLoaderFinished={() => setProgress(0)}
        />
        <Navbar
          addToCart={addToCart}
          cart={cart}
          removeFromCart={removeFromCart}
          clearCart={clearCart}
          subTotal={subTotal}
          cartLength={cartLength}
          loggedIn={loggedIn}
          logout={logout}
          userData={userData}
        />
        <div className="min-h-[40vh] overflow-x-hidden">
          <Component
            buyNow={buyNow}
            addToCart={addToCart}
            cart={cart}
            removeFromCart={removeFromCart}
            clearCart={clearCart}
            cartLength={cartLength}
            subTotal={subTotal}
            loggedIn={loggedIn}
            userData={userData}
            {...pageProps}
          />

          <ToastContainer
            position="bottom-left"
            autoClose={5000}
            hideProgressBar={false}
            newestOnTop={false}
            closeOnClick
            rtl={false}
            pauseOnFocusLoss
            draggable
            pauseOnHover
            theme="light"
          />
        </div>
        <Footer />
      </Provider>
    </>
  );
}

