const Sidenav = ({ userData }) => {
    const [collapse, setCollapse] = useState(true);

    const toggleCollapse = () => {
        if (window.innerWidth > 575) {
            return setCollapse(true);
        }
        return setCollapse(prevState => !prevState);
    };

    const handleWindowResizeEvent = () => {
        if (window.innerWidth > 575) {
            setCollapse(true);
        }
    };

    useLayoutEffect(() => {
