          {t('map.legend.all')}
        </LegChip>
        {days.map((d, i) => (
          <LegChip
            key={d.id}
            active={mapFilter === d.id}
            color={d.color}
            onClick={() => setMapFilter(mapFilter === d.id ? null : d.id)}
          >
            <span className="size-2 shrink-0 rounded-full" style={{ background: d.color }} />
            {t('map.legend.dayShort', { n: i + 1 })}
          </LegChip>
        ))}
