              <PrevNextButton
                prevButtonOnClick={() => addStage(1)}
                nextButtonOnClick={handleButtonClick}
              />
            </MyBookingInfoContainer>
          </RightSection>
        </Container>
      ) : (
        <Container>
          <LeftSection>
            <TicketMethodTicketlink
              setIsValidate={setIsValidate}
              errorArray={errorArray}
              handleChecked={handleChecked}
            />
          </LeftSection>
          <RightSection>
